import numpy as np

# Try to locate real dev_24 data; fall back to factor-matched synthetic replicas.
data = None
for name in ('dev_24', 'DEV_24', 'instances', 'suite'):
    obj = globals().get(name)
    if obj is not None:
        data = obj
        break
if data is None:
    loader = globals().get('load_suite') or globals().get('load_instances')
    if callable(loader):
        try:
            data = loader('cvrp_dev_hetero_24')
        except Exception:
            data = None

used_real = data is not None
insts = []
if used_real:
    try:
        for it in data:
            coords = np.asarray(it['coords'], dtype=float)
            demands = np.asarray(it['demands'], dtype=float)
            cap = float(it['capacity'])
            insts.append((coords, demands, cap))
    except Exception:
        insts = []
        used_real = False

if not insts:
    rng = np.random.default_rng(20261124)
    # 24 replicas matching dev_24 orthogonal factors: size{50,100} x spatial{clustered,uniform}
    # x depot{centre,eccentric} x capacity{tight,loose} x demand{uniform,bimodal}
    for k in range(24):
        n = 50 if k % 2 == 0 else 100
        clustered = (k // 2) % 3 == 0
        eccentric = (k // 3) % 2 == 0
        tight = (k // 4) % 2 == 0
        bimodal = (k // 6) % 2 == 0
        if clustered:
            centers = rng.uniform(0, 1, size=(4, 2))
            pts = centers[rng.integers(0, 4, size=n)] + rng.normal(0, 0.06, size=(n, 2))
        else:
            pts = rng.uniform(0, 1, size=(n, 2))
        depot = np.array([[0.5, 0.5]]) if not eccentric else np.array([[0.02, 0.02]])
        coords = np.vstack([depot, pts])
        if bimodal:
            demands = np.where(rng.random(n) < 0.5, rng.uniform(1, 4, n), rng.uniform(12, 18, n))
        else:
            demands = rng.uniform(1, 15, n)
        total = demands.sum()
        cap = total / (n / 6.0) if tight else total / (n / 12.0)
        insts.append((coords, demands, float(cap)))

def cw(coords, demands, cap, lam, mu, beta):
    n = len(demands)
    d = np.linalg.norm(coords[:, None, :] - coords[None, :, :], axis=2)
    scale = float(np.mean(d[0, 1:]))
    ii, jj = np.triu_indices(n, k=1)
    ii = ii + 1; jj = jj + 1
    d0i, d0j, dij = d[0, ii], d[0, jj], d[ii, jj]
    sav = d0i + d0j - dij
    m = sav > 1e-12
    ii, jj, d0i, d0j, dij, sav = ii[m], jj[m], d0i[m], d0j[m], dij[m], sav[m]
    fill = np.clip((demands[ii - 1] + demands[jj - 1]) / cap, 0, 1)
    score = (d0i + d0j - lam * dij + mu * np.abs(d0i - d0j)) / scale + beta * fill
    order = np.argsort(-score, kind='stable')
    routes = {i: [i] for i in range(1, n + 1)}
    loads = {i: float(demands[i - 1]) for i in range(1, n + 1)}
    owner = {i: i for i in range(1, n + 1)}
    for t in order:
        a, b = int(ii[t]), int(jj[t])
        ra, rb = owner[a], owner[b]
        if ra == rb:
            continue
        if loads[ra] + loads[rb] > cap + 1e-9:
            continue
        Ra, Rb = routes[ra], routes[rb]
        if Ra[0] == a and Rb[-1] == b:
            new = Rb + Ra
        elif Ra[-1] == a and Rb[0] == b:
            new = Ra + Rb
        elif Ra[0] == a and Rb[0] == b:
            new = Ra[::-1] + Rb
        elif Ra[-1] == a and Rb[-1] == b:
            new = Ra + Rb[::-1]
        else:
            continue
        routes[ra] = new
        loads[ra] += loads[rb]
        for v in Rb:
            owner[v] = ra
        del routes[rb]; del loads[rb]
    total = 0.0
    for r in routes.values():
        seq = [0] + r + [0]
        total += float(sum(d[seq[t2], seq[t2 + 1]] for t2 in range(len(seq) - 1)))
    return total

variants = {'classic': (1.0, 0.0, 0.0), 'gen_1.05': (1.05, 0.10, 0.10),
            'gen_1.10': (1.10, 0.10, 0.10), 'gen_1.15': (1.15, 0.12, 0.08)}
means = {}
for name, (lam, mu, beta) in variants.items():
    vals = [cw(c, q, Q, lam, mu, beta) for c, q, Q in insts]
    means[name] = float(np.mean(vals))
base = means['classic']
RESULT = {
    'used_real_dev24': bool(used_real),
    'n_instances': len(insts),
    'mean_tour_by_variant': means,
    'pct_gain_vs_classic': {k: round(100.0 * (base - v) / base, 4) for k, v in means.items()},
    'best_variant': min(means, key=means.get),
}
